package middlewares

import (
	"context"
	"encoding/json"

	"github.com/cloudevents/sdk-go/v2/event"
	"github.com/go-playground/validator/v10"
	"github.com/albe2669/asyncapi-codegen/pkg/extensions"
)

// CloudEventsValidation returns a middleware that validates CloudEvents
// messages in structured content mode: the broker payload is a CloudEvents
// envelope whose data field holds the payload, as generated by
// asyncapi-codegen for messages declaring a
// 'application/cloudevents+json' contentType.
//
// newPayload must return a pointer to a fresh payload value to decode the
// event data into, for example:
//
//	middlewares.CloudEventsValidation(validator.New(), func() any { return &UserMessagePayload{} })
//
// The middleware first checks that the envelope is a valid CloudEvents
// event (required attributes and spec version), then unmarshals the event
// data into that value and validates it. If any step fails, it returns an
// error, which aborts processing of the message — so invalid messages
// never reach user code (on reception) and are not sent (on publication).
//
// A fresh value is created for every message, so the middleware is safe
// for concurrent use.
func CloudEventsValidation(validate *validator.Validate, newPayload func() any) extensions.Middleware {
	return func(ctx context.Context, msg *extensions.BrokerMessage, next extensions.NextMiddleware) error {
		ev := event.New()

		if err := json.Unmarshal(msg.Payload, &ev); err != nil {
			return err
		}

		if err := ev.Validate(); err != nil {
			return err
		}

		payload := newPayload()

		if err := ev.DataAs(payload); err != nil {
			return err
		}

		if err := validate.Struct(payload); err != nil {
			return err
		}

		return next(ctx)
	}
}
